/* Rainy Day: Cascadia — Episode 1 remake runtime (v1).
 * Loaded once by the render roots (after gsap + rainy-day-rig-v5.js). The part compositions carry the static DOM
 * (shot clips, painted background <img>, SVG stage, bubbles, cards) generated by tools/build-ep01-remake-v1.py and
 * call EP.build(tl, SHOTS) to animate it. Everything is a pure function of timeline time (seek-safe):
 *   camera moves (GSAP on .cam), shakes (RD.shake on .shk), the characters (RD.drive), props, the clock fix,
 *   the coffee-cup shiver, falling debris, rain, the power-cut darkness, bubbles and cards (pop + settle).
 */
(function () {
  if (window.EP) return;
  const RD = window.RainyDay, NS = "http://www.w3.org/2000/svg", INK = "#14171C";
  const el = (tag, attrs, parent) => { const e = document.createElementNS(NS, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); if (parent) parent.appendChild(e); return e; };
  const f1 = (n) => (Math.round(n * 10) / 10).toString();
  const hash = (n) => { const x = Math.sin(n * 127.1 + 311.7) * 43758.5453; return (x - Math.floor(x)) * 2 - 1; };
  const camT = (c) => ({ x: 960 - c[0] * c[2], y: 540 - c[1] * c[2], scale: c[2] });

  // ---------------------------------------------------------------- props carried in the hands (ink + gray, no color)
  function propLaptop(g) { el("rect", { x: -34, y: -24, width: 68, height: 44, rx: 4, fill: "#5E646C", stroke: INK, "stroke-width": 4 }, g); el("rect", { x: -27, y: -18, width: 54, height: 30, rx: 2, fill: "#2B3036", stroke: INK, "stroke-width": 2 }, g); }
  function propAlbum(g) { el("rect", { x: -30, y: -22, width: 60, height: 42, rx: 3, fill: "#8A8F96", stroke: INK, "stroke-width": 4 }, g); el("line", { x1: -22, y1: -22, x2: -22, y2: 20, stroke: INK, "stroke-width": 3 }, g); el("rect", { x: -10, y: -12, width: 28, height: 20, fill: "#C9CDD2", stroke: INK, "stroke-width": 2 }, g); }
  function propPlant(g) {
    el("path", { d: "M-20 -6 L20 -6 L14 26 L-14 26 Z", fill: "#7A7F86", stroke: INK, "stroke-width": 4, "stroke-linejoin": "round" }, g);
    [[-4, -6, -26, -48], [0, -6, 2, -62], [4, -6, 26, -44], [0, -6, -14, -58], [2, -6, 16, -56]].forEach(([a, b, c, d]) =>
      el("path", { d: `M${a} ${b} Q ${(a + c) / 2 + 8} ${(b + d) / 2} ${c} ${d}`, fill: "none", stroke: INK, "stroke-width": 5, "stroke-linecap": "round" }, g));
    [[-26, -48], [2, -62], [26, -44], [-14, -58], [16, -56]].forEach(([x, y]) => el("ellipse", { cx: x, cy: y, rx: 9, ry: 5, fill: "#A3A8AE", stroke: INK, "stroke-width": 2.5, transform: `rotate(${x} ${x} ${y})` }, g));
  }
  function propBar(g) { el("rect", { x: -18, y: -7, width: 36, height: 14, rx: 3, fill: "#B5B9BE", stroke: INK, "stroke-width": 3 }, g); el("line", { x1: -6, y1: -7, x2: -6, y2: 7, stroke: INK, "stroke-width": 2 }, g); }
  const PROPS = { laptop: propLaptop, album: propAlbum, plant: propPlant, bar: propBar };

  function carryDrawer(stage, spec) {
    // spec: { items: [name...], appear: [t...], drop: t, dropTo: [[x,y]...], scale }
    const gs = spec.items.map((n) => { const g = el("g", { opacity: 0 }, stage); PROPS[n](g); return g; });
    const offs = [[0, 0], [0, -46], [2, -104]];
    let last = null;
    return (fig, t) => {
      const h1 = fig.hand("l"), h2 = fig.hand("r");
      const hx = (h1[0] + h2[0]) / 2, hy = (h1[1] + h2[1]) / 2, sc = spec.scale || fig.state.scale;
      gs.forEach((g, i) => {
        if (t < spec.appear[i]) { g.setAttribute("opacity", 0); return; }
        let x = hx + offs[i][0] * sc, y = hy - 8 * sc + offs[i][1] * sc;
        if (spec.drop !== undefined && t >= spec.drop) {
          const u = Math.min(1, (t - spec.drop - i * 0.12) / 0.4), e = Math.max(0, u) * Math.max(0, u);
          const to = spec.dropTo[i];
          x = x + (to[0] - x) * e; y = y + (to[1] - y) * e;
        }
        g.setAttribute("opacity", 1);
        g.setAttribute("transform", `translate(${f1(x)} ${f1(y)}) scale(${(sc * 0.9).toFixed(3)})`);
      });
      last = t;
    };
  }
  function snackDrawer(stage, spec) {
    const g = el("g", { opacity: 0 }, stage); propBar(g);
    return (fig, t) => {
      const on = t >= spec.t0 && t < spec.t1, h = fig.hand("r");
      g.setAttribute("opacity", on ? 1 : 0);
      if (on) g.setAttribute("transform", `translate(${f1(h[0])} ${f1(h[1] - 4)}) rotate(-15) scale(${(fig.state.scale * 0.9).toFixed(3)})`);
    };
  }

  // ---------------------------------------------------------------- effects drawn into the stage (bg coordinates)
  const FX = {
    // the painted clock reads ~10:10: cover its hands with a soft face-colored disc, draw clean hands
    clock(tl, s, stage, fx) {
      const g = el("g", {}, stage);
      const blurId = s.id + "-cb";
      const f = el("filter", { id: blurId, x: "-20%", y: "-20%", width: "140%", height: "140%" }, el("defs", {}, stage));
      el("feGaussianBlur", { stdDeviation: 1.6 }, f);
      el("circle", { cx: fx.cx, cy: fx.cy, r: fx.r, fill: fx.face, filter: `url(#${blurId})` }, g);
      if (fx.patch) el("line", { x1: fx.patch[0], y1: fx.patch[1], x2: fx.patch[2], y2: fx.patch[3], stroke: fx.face, "stroke-width": 9, "stroke-linecap": "round", filter: `url(#${blurId})` }, g);
      const [hh, mm] = fx.time.split(":").map(Number);
      const ha = ((hh % 12) + mm / 60) * 30, ma = mm * 6;
      el("line", { x1: fx.cx, y1: fx.cy, x2: fx.cx, y2: fx.cy - fx.r * 0.62, stroke: "#17191C", "stroke-width": 6.5, "stroke-linecap": "round", transform: `rotate(${ha} ${fx.cx} ${fx.cy})` }, g);
      el("line", { x1: fx.cx, y1: fx.cy, x2: fx.cx, y2: fx.cy - fx.r * 1.02, stroke: "#17191C", "stroke-width": 4.5, "stroke-linecap": "round", transform: `rotate(${ma} ${fx.cx} ${fx.cy})` }, g);
      el("circle", { cx: fx.cx, cy: fx.cy, r: 4.5, fill: "#17191C" }, g);
    },
    // the painted mug shivers: a clipped copy of the background around it, jittered
    mug(tl, s, stage, fx) {
      const cid = s.id + "-mc";
      const cp = el("clipPath", { id: cid }, el("defs", {}, stage));
      el("rect", { x: fx.x, y: fx.y, width: fx.w, height: fx.h }, cp);
      const wrap = el("g", { "clip-path": `url(#${cid})` }, stage);
      const img = el("image", { href: s.bgSrc, x: 0, y: 0, width: 1920, height: 1080, style: "filter:" + s.bgFilter }, wrap);
      const p = { t: 0 }, dur = fx.t1 - fx.t0;
      const apply = (t) => {
        const env = Math.min(1, t / 0.6) * fx.amp, k = Math.floor(t * 28);
        img.setAttribute("x", f1(hash(k * 3 + 1) * env)); img.setAttribute("y", f1(hash(k * 5 + 2) * env * 0.5));
      };
      apply(0);
      tl.fromTo(p, { t: 0 }, { t: dur, duration: dur, ease: "none", onUpdate: () => apply(p.t) }, s.t0 + fx.t0);
    },
    // plaster bits / glass falling
    debris(tl, s, stage, fx) {
      const bits = [];
      for (let i = 0; i < fx.n; i++) {
        const w = 4 + 6 * Math.abs(hash(i + 3));
        bits.push({ e: el("rect", { width: f1(w), height: f1(w * 0.7), fill: i % 3 ? "#9EA3A9" : "#D9DCE0", stroke: INK, "stroke-width": 1.5, opacity: 0 }, stage),
          x: fx.x0 + (fx.x1 - fx.x0) * (hash(i * 7 + 1) + 1) / 2, d: (hash(i * 11) + 1) / 2 * (fx.t1 - fx.t0 - 0.6), r: hash(i * 13) * 200 });
      }
      const p = { t: 0 }, dur = fx.t1 - fx.t0;
      const apply = (t) => bits.forEach((b) => {
        const u = t - b.d;
        if (u < 0) { b.e.setAttribute("opacity", 0); return; }
        const y = Math.min(fx.y1, fx.y0 + 0.5 * 2400 * u * u);
        b.e.setAttribute("opacity", 1);
        b.e.setAttribute("transform", `translate(${f1(b.x)} ${f1(y)}) rotate(${f1(b.r * u)})`);
      });
      apply(0);
      tl.fromTo(p, { t: 0 }, { t: dur, duration: dur, ease: "none", onUpdate: () => apply(p.t) }, s.t0 + fx.t0);
    },
    gobag(tl, s, stage, fx) {
      const g = RD.goBag(stage, fx.x, fx.y, fx.scale);
      if (fx.hideAt !== undefined) tl.set(g, { attr: { opacity: 0 } }, s.t0 + fx.hideAt);
    },
    // one tiny warm light far down in the dark (the ONLY other warm spot in the episode), flickering on
    light(tl, s, stage, fx) {
      const gid = s.id + "-lg";
      const rg = el("radialGradient", { id: gid }, el("defs", {}, stage));
      el("stop", { offset: "0%", "stop-color": "#FFD27A", "stop-opacity": 0.95 }, rg);
      el("stop", { offset: "35%", "stop-color": "#FFB347", "stop-opacity": 0.45 }, rg);
      el("stop", { offset: "100%", "stop-color": "#FFB347", "stop-opacity": 0 }, rg);
      const g = el("g", { opacity: 0 }, stage);
      el("circle", { cx: fx.x, cy: fx.y, r: 26, fill: `url(#${gid})` }, g);
      el("circle", { cx: fx.x, cy: fx.y, r: 3.2, fill: "#FFE3A8" }, g);
      const seq = [[0, 0.7], [0.08, 0], [0.3, 0.9], [0.38, 0.2], [0.55, 1], [1.4, 0.85], [1.6, 1]];
      seq.forEach(([dt, o]) => tl.set(g, { attr: { opacity: o } }, s.t0 + fx.t0 + dt));
      const p = { t: 0 }, dur = s.dur - fx.t0 - 1.6;
      if (dur > 0) tl.fromTo(p, { t: 0 }, { t: dur, duration: dur, ease: "none", onUpdate: () => g.setAttribute("opacity", (0.82 + 0.18 * hash(Math.floor(p.t * 9))).toFixed(2)) }, s.t0 + fx.t0 + 1.6);
    },
    // hand-crank emergency radio, in the series' ink style; crank turns, static then clean sound arcs
    radio(tl, s, stage, fx) {
      const g = el("g", { transform: `translate(${fx.x} ${fx.y}) scale(${fx.scale})` }, stage);
      el("ellipse", { cx: 0, cy: 118, rx: 250, ry: 22, fill: INK, opacity: 0.25 }, g);
      el("line", { x1: 120, y1: -96, x2: 190, y2: -300, stroke: INK, "stroke-width": 10, "stroke-linecap": "round" }, g);
      el("circle", { cx: 190, cy: -300, r: 9, fill: INK }, g);
      el("path", { d: "M-150 -110 Q -150 -150 -100 -150 L 100 -150 Q 150 -150 150 -110", fill: "none", stroke: INK, "stroke-width": 14, "stroke-linecap": "round" }, g);
      el("rect", { x: -230, y: -100, width: 460, height: 210, rx: 26, fill: "#6E747C", stroke: INK, "stroke-width": 8 }, g);
      el("rect", { x: -200, y: -72, width: 190, height: 156, rx: 14, fill: "#4C5259", stroke: INK, "stroke-width": 5 }, g);
      for (let i = 0; i < 7; i++) el("line", { x1: -186, y1: -52 + i * 20, x2: -24, y2: -52 + i * 20, stroke: "#2A2E33", "stroke-width": 5, "stroke-linecap": "round" }, g);
      el("rect", { x: 20, y: -72, width: 180, height: 56, rx: 8, fill: "#C9CDD2", stroke: INK, "stroke-width": 5 }, g);
      for (let i = 0; i < 9; i++) el("line", { x1: 36 + i * 19, y1: -64, x2: 36 + i * 19, y2: i % 2 ? -52 : -46, stroke: INK, "stroke-width": 2.5 }, g);
      el("line", { x1: 120, y1: -70, x2: 120, y2: -20, stroke: "#17191C", "stroke-width": 4 }, g);
      el("circle", { cx: 70, cy: 40, r: 28, fill: "#9AA0A7", stroke: INK, "stroke-width": 5 }, g);
      el("circle", { cx: 150, cy: 40, r: 20, fill: "#9AA0A7", stroke: INK, "stroke-width": 5 }, g);
      // crank on the right side
      const crank = el("g", { transform: "translate(250 10)" }, g);
      el("circle", { cx: 0, cy: 0, r: 16, fill: "#4C5259", stroke: INK, "stroke-width": 5 }, crank);
      const arm = el("g", {}, crank);
      el("line", { x1: 0, y1: 0, x2: 0, y2: 78, stroke: INK, "stroke-width": 12, "stroke-linecap": "round" }, arm);
      el("rect", { x: -12, y: 70, width: 24, height: 40, rx: 8, fill: "#8A9097", stroke: INK, "stroke-width": 5 }, arm);
      // sound: static squiggles, then clean arcs
      const sq = el("g", { opacity: 0 }, g), arcs = el("g", { opacity: 0 }, g);
      const squig = [];
      for (let i = 0; i < 5; i++) squig.push(el("path", { fill: "none", stroke: INK, "stroke-width": 4, "stroke-linecap": "round" }, sq));
      for (let i = 0; i < 3; i++) el("path", { d: `M ${-260 - i * 34} ${-70 - i * 20} Q ${-300 - i * 44} 0 ${-260 - i * 34} ${70 + i * 20}`, fill: "none", stroke: INK, "stroke-width": 6, "stroke-linecap": "round" }, arcs);
      const p = { t: 0 }, dur = s.dur;
      const apply = (t) => {
        const crankOn = t >= (fx.crank0 || 0) && t < (fx.crank1 === undefined ? dur : fx.crank1);
        arm.setAttribute("transform", `rotate(${f1(crankOn ? (t - (fx.crank0 || 0)) * 420 : 0)})`);
        const st = fx.static0 !== undefined && t >= fx.static0 && (fx.clean0 === undefined || t < fx.clean0);
        sq.setAttribute("opacity", st ? 1 : 0);
        if (st) squig.forEach((e, i) => {
          const k = Math.floor(t * 12) + i * 7, x0 = -250 - i * 26, y0 = -90 + i * 40;
          let d = `M${x0} ${y0}`;
          for (let j = 1; j <= 5; j++) d += ` L${f1(x0 - j * 16)} ${f1(y0 + hash(k * 13 + j) * 14)}`;
          e.setAttribute("d", d);
        });
        arcs.setAttribute("opacity", fx.clean0 !== undefined && t >= fx.clean0 ? (0.6 + 0.4 * Math.abs(Math.sin(t * 6))).toFixed(2) : 0);
      };
      apply(0);
      tl.fromTo(p, { t: 0 }, { t: dur, duration: dur, ease: "none", onUpdate: () => apply(p.t) }, s.t0);
    },
  };

  function popIn(tl, node, t, settle) {
    tl.fromTo(node, { opacity: 0, scale: 0.62, rotation: -4 }, { opacity: 1, scale: 1.05, rotation: -1, duration: 0.24, ease: "back.out(2.2)" }, t);
    tl.to(node, { scale: 1, rotation: 0, duration: 0.3, ease: "sine.out" }, t + 0.24);
    if (settle) tl.to(node, { scale: 1.02, duration: settle, ease: "none" }, t + 0.54);
  }

  function build(tl, shots) {
    shots.forEach((s) => {
      const root = document.getElementById(s.id);
      if (!root) return;
      const cam = root.querySelector(".cam"), shk = root.querySelector(".shk"), stage = root.querySelector("svg.stage");
      if (cam && s.cam) {
        gsap.set(cam, { transformOrigin: "0 0" });
        tl.fromTo(cam, camT(s.cam.from), Object.assign(camT(s.cam.to), { duration: s.dur, ease: s.cam.ease || "sine.inOut" }), s.t0);
      }
      if (s.shake) RD.shake(tl, shk, { start: s.t0 + s.shake.t0, end: s.t0 + s.shake.t1, amp: s.shake.amp, rot: s.shake.rot || 0.5, freq: s.shake.freq || 11, rampIn: s.shake.rampIn, rampOut: s.shake.rampOut });
      (s.fx || []).forEach((fx) => FX[fx.type](tl, s, stage, fx));
      (s.figs || []).forEach((f, i) => {
        const seg0 = f.segs[0];
        const fig = RD.figure(stage, Object.assign({ character: f.who, x: seg0.walk ? seg0.walk.x0 : seg0.x, y: seg0.walk ? seg0.walk.y0 : seg0.y, scale: seg0.scale, facing: seg0.facing }, f.opts || {}));
        let onDraw;
        if (f.carry) onDraw = carryDrawer(stage, f.carry);
        if (f.snack) onDraw = snackDrawer(stage, f.snack);
        RD.drive(tl, fig, f.segs, { start: s.t0, end: s.t0 + s.dur, onDraw });
      });
      if (s.rain) RD.rain(tl, root.querySelector("svg.rain"), { start: s.t0, end: s.t0 + s.dur, count: 120, opacity: s.rain, stroke: "#E2E5E8", seed: 3 + s.n, length: 40, angle: 10 });
      const dark = root.querySelector(".dark");
      if (dark && s.dark) s.dark.forEach(([t, o]) => tl.set(dark, { opacity: o }, s.t0 + t));
      const bub = root.querySelector(".bubble");
      if (bub && s.bubble) {
        tl.set(bub, { opacity: 0 }, s.t0);
        popIn(tl, bub, s.t0 + (s.bubble.t0 || 0.15), Math.max(0.1, s.dur - (s.bubble.t0 || 0.15) - 0.75));
        tl.to(bub, { opacity: 0, duration: 0.18 }, s.t0 + s.dur - 0.2);
      }
      const card = root.querySelector(".cardwrap");
      if (card && s.card) {
        tl.set(card, { opacity: 0 }, s.t0);
        popIn(tl, card, s.t0 + (s.card.t0 || 0.08), Math.max(0.1, s.dur - 0.8));
        if (!s.card.hold) tl.to(card, { opacity: 0, duration: 0.16 }, s.t0 + s.dur - 0.18);
      }
    });
  }
  window.EP = { build, FX, PROPS };
})();
